INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(5, 'walking-pace-awareness', 'painting', 'A3', 'Walking Pace Awareness', '步伐節奏', 'Pay attention to your steps while walking. Tap the screen to the beat to record your walking rhythm.', '行走時留意自己的步伐，以打拍子的點觸方式，留下您走路的節奏。', '步伐節奏往往反映內在心理狀態。透過留意自己的腳步聲與行走速度，可察覺是否過於急促，並為自我調節創造空間，有助減低緊張感與提升身心覺察。', 'Walking pace reflects mental state. Listening to footsteps reveals urgency and creates space for regulation.', '港鐵站(鰂魚涌)、港鐵站(會展)、港鐵站(大埔墟)、港鐵站(錦上路)、港鐵站(荃灣)', 'MTR(Quarry Bay), MTR(Exhibition Centre), MTR(Tai Po Market), MTR(Kam Sheung Road), MTR(Tsuen Wan)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"qub","name_zh":"港鐵站(鰂魚涌)","name_en":"MTR(Quarry Bay)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.2878871867651,"lng":114.20974916640195,"x":66.21,"y":63.4},{"brand":"MTR","code":"exc","name_zh":"港鐵站(會展)","name_en":"MTR(Exhibition Centre)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.282140151501554,"lng":114.17550176784363,"x":59.8,"y":64.54},{"brand":"MTR","code":"tpm","name_zh":"港鐵站(大埔墟)","name_en":"MTR(Tai Po Market)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.444545527654668,"lng":114.17048239743535,"x":60.67,"y":32.15},{"brand":"MTR","code":"ksr","name_zh":"港鐵站(錦上路)","name_en":"MTR(Kam Sheung Road)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.434766510854786,"lng":114.0635279442419,"x":44.91,"y":36.06},{"brand":"MTR","code":"tw","name_zh":"港鐵站(荃灣)","name_en":"MTR(Tsuen Wan)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.37354019,"lng":114.11729148357115,"x":49.08,"y":47.3}]', '{"message_zh":"您留意到自己的節奏。\\n覺察本身，已是一種調節。\\n","message_en":"Awareness itself is regulation."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(6, 'carriage-white-noise', 'painting', 'A4', 'Carriage White Noise', '車廂白噪音', 'Listen to the ambient background noise and choose the feeling it brings to you.', '聆聽環境背景聲，選擇它帶來的感受。', '穩定而持續的背景聲，能為大腦提供安全感。短暫留意車廂或站內的環境白噪音，有助降低過度刺激，讓神經系統獲得片刻休息與平靜。', 'Stable background sounds provide safety and calm the nervous system.', '港鐵站(粉嶺)、港鐵站(鑽石山)、港鐵站(顯徑)、港鐵站(調景嶺)、港鐵站(沙田圍)', 'MTR(Fanling), MTR(Diamond Hill), MTR(Hin Keng), MTR(Tiu Keng Leng), MTR(Sha Tin Wai)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"fan","name_zh":"港鐵站(粉嶺)","name_en":"MTR(Fanling)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.492071519500143,"lng":114.13869196698117,"x":60.65,"y":25.57},{"brand":"MTR","code":"dhl","name_zh":"港鐵站(鑽石山)","name_en":"MTR(Diamond Hill)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.340014077194,"lng":114.20170069828723,"x":63.36,"y":51.5},{"brand":"MTR","code":"hk","name_zh":"港鐵站(顯徑)","name_en":"MTR(Hin Keng)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.36383307314707,"lng":114.17079159525757,"x":57.25,"y":46.2},{"brand":"MTR","code":"tkl","name_zh":"港鐵站(調景嶺)","name_en":"MTR(Tiu Keng Leng)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.304481133388695,"lng":114.25286689561074,"x":73.76,"y":60.36},{"brand":"MTR","code":"stw","name_zh":"港鐵站(沙田圍)","name_en":"MTR(Sha Tin Wai)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.377023822376753,"lng":114.19497835288844,"x":62.47,"y":44.44}]', '{"message_zh":"您容許背景聲存在。\\n有時，不需要安靜，也能平靜。\\n","message_en":"Calm doesn’t always require silence."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(7, 'handrail-temperature', 'quiz', 'T1', 'Handrail Temperature', '扶手溫度', 'Notice the texture or temperature of the object in your hand, and select what you feel.', '留意手上物品觸感或溫度，選擇您的感受。', '觸覺是最直接連結身體與當下的感官。透過留意物件的溫度與質感，可將注意力由思緒拉回身體，建立即時的存在感，並有助提升穩定與安定感。', 'Touch anchors attention in the body. Noticing temperature supports stability.', '港鐵站(上水)、港鐵站(荔枝角)、港鐵站(車公廟)、港鐵站(石硤尾)、港鐵站(九龍灣)', 'MTR(Sheung Shui), MTR(Lai Chi Kok), MTR(Che Kung Temple), MTR(Shek Kip Mei), MTR(Kowloon Bay)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"shs","name_zh":"港鐵站(上水)","name_en":"MTR(Sheung Shui)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.50125845585908,"lng":114.12795184011195,"x":57.68,"y":24.84},{"brand":"MTR","code":"lck","name_zh":"港鐵站(荔枝角)","name_en":"MTR(Lai Chi Kok)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.337259139161915,"lng":114.14803060389478,"x":53.51,"y":53.96},{"brand":"MTR","code":"ckt","name_zh":"港鐵站(車公廟)","name_en":"MTR(Che Kung Temple)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.37475806588989,"lng":114.18595306462889,"x":61.71,"y":45.14},{"brand":"MTR","code":"skm","name_zh":"港鐵站(石硤尾)","name_en":"MTR(Shek Kip Mei)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.33211654344188,"lng":114.16880229492105,"x":59.46,"y":51.11},{"brand":"MTR","code":"klb","name_zh":"港鐵站(九龍灣)","name_en":"MTR(Kowloon Bay)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.32323874838126,"lng":114.21395434816758,"x":64.31,"y":54.83}]', '{"message_zh":"您重新感受到身體。\\n當下，其實一直都在您身邊。\\n","message_en":"You reconnected with your body.","question_zh":"剛才感受到的觸感是？","question_en":"How did the touch feel to you?","options":[{"label_zh":"溫暖","label_en":"Warm","value":"a","message_zh":"您重新感受到身體。\\n當下，其實一直都在您身邊。\\n","message_en":"You reconnected with your body."},{"label_zh":"偏冷","label_en":"Cool","value":"b","message_zh":"您重新感受到身體。\\n當下，其實一直都在您身邊。\\n","message_en":"You reconnected with your body."},{"label_zh":"平常","label_en":"Neutral","value":"c","message_zh":"您重新感受到身體。\\n當下，其實一直都在您身邊。\\n","message_en":"You reconnected with your body."},{"label_zh":"不太留意到","label_en":"Not noticed","value":"d","message_zh":"您重新感受到身體。\\n當下，其實一直都在您身邊。\\n","message_en":"You reconnected with your body."}]}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(8, 'grounded-steps', 'video', 'T2', 'Grounded Steps', '腳下實感', 'Feel your feet connecting with the ground as you walk, and follow the audio guide for a brief walking exercise.', '行走時感受腳踏地面，聽隨聲帶進行一次簡短的行路練習。', '感受雙腳與地面的接觸，有助重新建立身體的穩定感。這種觸覺覺察能減少飄忽與分心狀態，並協助身體在移動中保持平衡與安全感。', 'Feeling feet on the ground restores bodily stability and balance.', '港鐵站(油麻地)、港鐵站(海洋公園)、港鐵站(大圍)、港鐵站(將軍澳)', 'MTR(Yau Ma Tei), MTR(Ocean Park), MTR(Tai Wai), MTR(Tseung Kwan O)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"ymt","name_zh":"港鐵站(油麻地)","name_en":"MTR(Yau Ma Tei)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.31282825606428,"lng":114.17068028745008,"x":58.71,"y":58.78},{"brand":"MTR","code":"ocp","name_zh":"港鐵站(海洋公園)","name_en":"MTR(Ocean Park)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.248695108405094,"lng":114.17444338927963,"x":60.04,"y":71.8},{"brand":"MTR","code":"twa","name_zh":"港鐵站(大圍)","name_en":"MTR(Tai Wai)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.372705875485874,"lng":114.17861748695312,"x":57.17,"y":41.36},{"brand":"MTR","code":"tko","name_zh":"港鐵站(將軍澳)","name_en":"MTR(Tseung Kwan O)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.307454285520247,"lng":114.26001861933692,"x":73.86,"y":58.11}]', '{"message_zh":"您感受到了腳踏實地。\\n穩定，往往從最基本的位置開始。\\n","message_en":"Stability starts from the ground.","video_url":"https://330day-s3-production.s3.ap-east-1.amazonaws.com/videos/newlife-video-breathing.mov"}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(9, 'vibration-awareness', 'quiz', 'T3', 'Vibration Awareness', '震動感知', 'Notice the vibration of the floor as the train moves. Select the part of your body where you feel the vibration most strongly.', '留意列車移動時地面的震動，選擇您最明顯感受到震動的身體部位。', '身體能即時感知環境中的微細震動。透過留意列車行駛或啟動時的震動感，可加強身體覺察，避免長時間停留於過度思考狀態，讓注意力回到身體經驗。', 'The body detects subtle vibration. Awareness brings attention out of overthinking.', '港鐵站(太古)、港鐵站(黃埔)、港鐵站(太和)、港鐵站(朗屏)、港鐵站(啟德)', 'MTR(Tai Koo), MTR(Whampoa), MTR(Tai Wo), MTR(Long Ping), MTR(Kai Tak)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"tk","name_zh":"港鐵站(太古)","name_en":"MTR(Tai Koo)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.284648526320005,"lng":114.21636095630055,"x":67.37,"y":64.24},{"brand":"MTR","code":"whp","name_zh":"港鐵站(黃埔)","name_en":"MTR(Whampoa)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.30502772091467,"lng":114.18955019857363,"x":61.0,"y":58.23},{"brand":"MTR","code":"two","name_zh":"港鐵站(太和)","name_en":"MTR(Tai Wo)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.450998918610367,"lng":114.16122125409458,"x":62.04,"y":27.66},{"brand":"MTR","code":"lpi","name_zh":"港鐵站(朗屏)","name_en":"MTR(Long Ping)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.44767718108014,"lng":114.0254888841721,"x":38.56,"y":35.27},{"brand":"MTR","code":"kit","name_zh":"港鐵站(啟德)","name_en":"MTR(Kai Tak)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.330569288069338,"lng":114.19955007334084,"x":62.6,"y":55.04}]', '{"message_zh":"您留意到細微的變化。\\n身體一直在回應世界。\\n","message_en":"Your body is responding to the world.","question_zh":"您最明顯感受到震動的身體部位是？","question_en":"Where did you feel the vibration most clearly?","options":[{"label_zh":"腳下","label_en":"Feet","value":"a","message_zh":"您留意到細微的變化。\\n身體一直在回應世界。\\n","message_en":"Your body is responding to the world."},{"label_zh":"手部","label_en":"Hands","value":"b","message_zh":"您留意到細微的變化。\\n身體一直在回應世界。\\n","message_en":"Your body is responding to the world."},{"label_zh":"身體","label_en":"Body","value":"c","message_zh":"您留意到細微的變化。\\n身體一直在回應世界。\\n","message_en":"Your body is responding to the world."},{"label_zh":"不太明顯","label_en":"Hardly noticed","value":"d","message_zh":"您留意到細微的變化。\\n身體一直在回應世界。\\n","message_en":"Your body is responding to the world."}]}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(10, 'object-in-hand', 'painting', 'T4', 'Object in Hand', '手中物件', 'Sketch the outline of the object in your hand.', '描繪出手中物件的外形。', '日常隨身物件常與安全感連結。透過短暫留意手中物件的重量與觸感，可喚起熟悉與安心的感受，協助穩定當下狀態並減少不安。', 'Familiar objects carry safety. Noticing them stabilises emotion.', '港鐵站(大窩口)、港鐵站(尖東)、港鐵站(宋皇臺)、港鐵站(落馬洲)、港鐵站(柯士甸)', 'MTR(Tai Wo Hau), MTR(East Tsim Sha Tsui), MTR(Sung Wong Toi), MTR(Lok Ma Chau), MTR(Austin)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"twh","name_zh":"港鐵站(大窩口)","name_en":"MTR(Tai Wo Hau)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.370787779913396,"lng":114.12505947054642,"x":50.31,"y":48.0},{"brand":"MTR","code":"ets","name_zh":"港鐵站(尖東)","name_en":"MTR(East Tsim Sha Tsui)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.294813979559237,"lng":114.17343261836396,"x":59.72,"y":60.46},{"brand":"MTR","code":"swt","name_zh":"港鐵站(宋皇臺)","name_en":"MTR(Sung Wong Toi)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.325909359242676,"lng":114.19130067362552,"x":60.88,"y":54.93},{"brand":"MTR","code":"lmc","name_zh":"港鐵站(落馬洲)","name_en":"MTR(Lok Ma Chau)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.514828831422598,"lng":114.06564561508425,"x":41.93,"y":25.48},{"brand":"MTR","code":"aus","name_zh":"港鐵站(柯士甸)","name_en":"MTR(Austin)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.305291330845883,"lng":114.16610329031731,"x":56.3,"y":58.99}]', '{"message_zh":"您握住了熟悉的觸感。\\n安心，有時很簡單。\\n","message_en":"Comfort can be simple."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(11, 'air-change-awareness', 'painting', 'S1', 'Air Change Awareness', '空氣變化', 'Notice changes in the air as you walk, and select your impression.', '行走時留意空氣感覺的變化，選擇您的感受。是侷促/暢快/平穩', '空氣的轉換往往反映空間與環境的改變。透過留意空氣感覺的差異，有助提升對場景轉移的覺察，並提醒自己正在進入新的情境與狀態。', 'Changes in air reflect environment shifts and support transition awareness.', '港鐵站(長沙灣)、港鐵站(土瓜灣)、港鐵站(第一城)', 'MTR(Cheung Sha Wan), MTR(To Kwa Wan), MTR(City One)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"csw","name_zh":"港鐵站(長沙灣)","name_en":"MTR(Cheung Sha Wan)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.335609132780665,"lng":114.15599588756271,"x":54.7,"y":54.58},{"brand":"MTR","code":"tkw","name_zh":"港鐵站(土瓜灣)","name_en":"MTR(To Kwa Wan)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.317308896887468,"lng":114.18760074739181,"x":60.65,"y":56.47},{"brand":"MTR","code":"cio","name_zh":"港鐵站(第一城)","name_en":"MTR(City One)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.38290174095893,"lng":114.20369763126197,"x":63.37,"y":44.04}]', '{"message_zh":"您察覺到空氣的轉換。\\n每個空間，都在提醒您正在前行。\\n","message_en":"You noticed the environment shift."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(12, 'familiar-scent', 'painting', 'S2', 'Familiar Scent', '熟悉的氣味', 'Notice the scent in the air right now, and describe the feelings or memories it triggers.', '留意此刻的氣味，描述它帶來的感受或記憶。', '嗅覺與情緒記憶關係密切。某些熟悉氣味能迅速喚起過往經驗，透過覺察這種反應，有助理解自身情緒來源，並加深對內在狀態的認識。', 'Smell links to memory and emotion. Familiar scents clarify feelings.', '港鐵站(天后)、港鐵站(佐敦)、港鐵站(利東)、港鐵站(沙田)', 'MTR(Tin Hau), MTR(Jordan), MTR(Lei Tung), MTR(Sha Tin)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"thu","name_zh":"港鐵站(天后)","name_en":"MTR(Tin Hau)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.282419785038233,"lng":114.1917264974919,"x":62.5,"y":63.62},{"brand":"MTR","code":"jor","name_zh":"港鐵站(佐敦)","name_en":"MTR(Jordan)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.30478537909805,"lng":114.17166121766562,"x":58.52,"y":59.66},{"brand":"MTR","code":"let","name_zh":"港鐵站(利東)","name_en":"MTR(Lei Tung)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.241938833944843,"lng":114.15610104437118,"x":55.96,"y":74.45},{"brand":"MTR","code":"sti","name_zh":"港鐵站(沙田)","name_en":"MTR(Sha Tin)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.381823554714412,"lng":114.18698843497162,"x":58.99,"y":40.48}]', '{"message_zh":"您連結了一段記憶。\\n氣味，往往比文字更誠實。\\n","message_en":"Scents speak honestly."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(13, 'refreshing-breath', 'quiz', 'S3', 'Refreshing Breath', '清新一刻', 'Follow the rhythm to take a slow breath in and out. Select how you feel afterwards.', '跟隨節奏，進行一次緩慢吸氣與呼氣，選擇完成後的感受。', '有意識的呼吸能直接影響身心狀態。透過一次緩慢而專注的吸氣與呼氣，可為神經系統帶來短暫調節，讓身心重新回到較平穩的節奏。', 'Conscious breathing regulates mind and body.', '港鐵站(西灣河)、港鐵站(何文田)、港鐵站(南昌)、港鐵站(石門)', 'MTR(Sai Wan Ho), MTR(Ho Man Tin), MTR(Nam Cheong), MTR(Shek Mun)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"swh","name_zh":"港鐵站(西灣河)","name_en":"MTR(Sai Wan Ho)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.282098935416208,"lng":114.22190042318837,"x":68.61,"y":65.32},{"brand":"MTR","code":"hmt","name_zh":"港鐵站(何文田)","name_en":"MTR(Ho Man Tin)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.309358251764685,"lng":114.18273009943567,"x":61.04,"y":57.71},{"brand":"MTR","code":"nch","name_zh":"港鐵站(南昌)","name_en":"MTR(Nam Cheong)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.3267755986408,"lng":114.15368016018154,"x":55.4,"y":55.18},{"brand":"MTR","code":"shm","name_zh":"港鐵站(石門)","name_en":"MTR(Shek Mun)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.38769325100283,"lng":114.20834998905384,"x":64.62,"y":43.58}]', '{"message_zh":"您完成了一次呼吸。\\n不急，已經很好。\\n","message_en":"No rush—you’re doing well.","question_zh":"完成這次呼吸後，您的感受是？","question_en":"How do you feel after that breath?","options":[{"label_zh":"較放鬆","label_en":"More relaxed","value":"a","message_zh":"您完成了一次呼吸。\\n不急，已經很好。\\n","message_en":"No rush—you’re doing well."},{"label_zh":"較清醒","label_en":"More alert","value":"b","message_zh":"您完成了一次呼吸。\\n不急，已經很好。\\n","message_en":"No rush—you’re doing well."},{"label_zh":"較平穩","label_en":"More balanced","value":"c","message_zh":"您完成了一次呼吸。\\n不急，已經很好。\\n","message_en":"No rush—you’re doing well."},{"label_zh":"沒有特別感覺","label_en":"No noticeable change","value":"d","message_zh":"您完成了一次呼吸。\\n不急，已經很好。\\n","message_en":"No rush—you’re doing well."}]}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(14, 'the-scent-of-stillness', 'quiz', 'S4', 'The Scent of Stillness', '無味挑戰', 'Notice if the space is nearly scentless, and select the experience that fits best.', '留意空間是否近乎無味，選擇最貼近的體驗。', '當環境中沒有明顯氣味時，感官亦能稍作休息。覺察氣味的淡薄或不存在，本身也是一種細緻的感官體驗，有助帶來安靜與平衡感。', 'Minimal scent allows the senses to rest.', '港鐵站(葵興)、港鐵站(九龍塘)、港鐵站(天水圍)、港鐵站(香港)、港鐵站(大水坑)', 'MTR(Kwai Hing), MTR(Kowloon Tong), MTR(Tin Shui Wai), MTR(Hong Kong), MTR(Tai Shui Hang)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"khg","name_zh":"港鐵站(葵興)","name_en":"MTR(Kwai Hing)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.363056562402413,"lng":114.13121142602186,"x":50.29,"y":49.0},{"brand":"MTR","code":"ktt","name_zh":"港鐵站(九龍塘)","name_en":"MTR(Kowloon Tong)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.33715783531838,"lng":114.1760937990306,"x":60.76,"y":52.78},{"brand":"MTR","code":"tsw","name_zh":"港鐵站(天水圍)","name_en":"MTR(Tin Shui Wai)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.448220545896096,"lng":114.00474060410535,"x":32.74,"y":38.52},{"brand":"MTR","code":"hkg","name_zh":"港鐵站(香港)","name_en":"MTR(Hong Kong)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.28468012787878,"lng":114.15817909595697,"x":56.2,"y":63.59},{"brand":"MTR","code":"tsh","name_zh":"港鐵站(大水坑)","name_en":"MTR(Tai Shui Hang)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.40842362926005,"lng":114.22271706325687,"x":66.33,"y":42.9}]', '{"message_zh":"您感受到了平靜。\\n沒有刺激，也是一種體驗。\\n","message_en":"Stillness is an experience.","question_zh":"此刻空間的氣味狀態是？","question_en":"How would you describe the scent level in this space?","options":[{"label_zh":"幾乎沒有氣味","label_en":"Almost none","value":"a","message_zh":"您感受到了平靜。\\n沒有刺激，也是一種體驗。\\n","message_en":"Stillness is an experience."},{"label_zh":"很淡很淡","label_en":"Very light","value":"b","message_zh":"您感受到了平靜。\\n沒有刺激，也是一種體驗。\\n","message_en":"Stillness is an experience."},{"label_zh":"難以分辨","label_en":"Hard to tell","value":"c","message_zh":"您感受到了平靜。\\n沒有刺激，也是一種體驗。\\n","message_en":"Stillness is an experience."},{"label_zh":"沒有特別留意","label_en":"Not noticed","value":"d","message_zh":"您感受到了平靜。\\n沒有刺激，也是一種體驗。\\n","message_en":"Stillness is an experience."}]}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(15, 'taste-memory', 'painting', 'G1', 'Taste Memory', '回憶中的味道', 'Think of a favorite flavor, and select its taste category.', '想起一種喜愛的味道，選擇其味覺類型。', '味道往往承載情感與記憶。透過回想熟悉或喜愛的味道，可喚起正向情緒，為當下帶來安心與熟悉感，並有助舒緩疲勞與壓力。', 'Taste carries memory and emotion. Recalling it brings comfort.', '港鐵站(恆安)、港鐵站(海怡半島)、港鐵站(九龍)', 'MTR(Heng On), MTR(South Horizons), MTR(Kowloon)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"hon","name_zh":"港鐵站(恆安)","name_en":"MTR(Heng On)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.417319708417363,"lng":114.2257000625166,"x":67.85,"y":42.0},{"brand":"MTR","code":"shi","name_zh":"港鐵站(海怡半島)","name_en":"MTR(South Horizons)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.242858376718846,"lng":114.14874483440609,"x":50.15,"y":74.46},{"brand":"MTR","code":"kln","name_zh":"港鐵站(九龍)","name_en":"MTR(Kowloon)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.304302542313213,"lng":114.16147520120319,"x":56.34,"y":57.95}]', '{"message_zh":"您想起了一種熟悉的味道。\\n回憶，有時能安放情緒。\\n","message_en":"Memories can hold emotion."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(16, 'oral-awareness', 'quiz', 'G2', 'Oral Awareness', '口腔覺察', 'As you walk, notice the sensation inside your mouth, and choose the description that fits best.', '在行走中，留意此刻口腔的感覺，並選擇最貼近的描述。', '味覺不只來自食物，口腔本身亦會反映身體狀態。透過短暫留意口腔的乾濕、溫度與感覺變化，可喚醒味覺覺察，讓注意力由思緒回到身體，帶來片刻穩定與清醒感。', 'Taste awareness can exist without eating. Mouth sensations reconnect body awareness.', '港鐵站(炮台山)、港鐵站(馬鞍山)、港鐵站(火炭)', 'MTR(Fortress Hill), MTR(Ma On Shan), MTR(Fo Tan)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"foh","name_zh":"港鐵站(炮台山)","name_en":"MTR(Fortress Hill)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.287996110051637,"lng":114.19356390513038,"x":65.1,"y":62.86},{"brand":"MTR","code":"mos","name_zh":"港鐵站(馬鞍山)","name_en":"MTR(Ma On Shan)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.42481873990593,"lng":114.2316501368071,"x":69.01,"y":41.19},{"brand":"MTR","code":"fot","name_zh":"港鐵站(火炭)","name_en":"MTR(Fo Tan)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.3950801852613,"lng":114.19813766282377,"x":60.2,"y":40.15}]', '{"message_zh":"您留意到了身體的細微訊號。\\n覺察，本身已是一種照顧。\\n","message_en":"Awareness is care.","question_zh":"此刻，您口腔的感覺是？","question_en":"How does your mouth feel at this moment?","options":[{"label_zh":"偏乾","label_en":"Dry","value":"a","message_zh":"您留意到了身體的細微訊號。\\n覺察，本身已是一種照顧。\\n","message_en":"Awareness is care."},{"label_zh":"偏濕","label_en":"Moist","value":"b","message_zh":"您留意到了身體的細微訊號。\\n覺察，本身已是一種照顧。\\n","message_en":"Awareness is care."},{"label_zh":"平常","label_en":"Neutral","value":"c","message_zh":"您留意到了身體的細微訊號。\\n覺察，本身已是一種照顧。\\n","message_en":"Awareness is care."}]}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(17, 'anticipated-taste', 'quiz', 'G3', 'Anticipated Taste', '期待的味道', 'Think of the meal you\'re looking forward to most today, and choose the matching mood.', '想起今天最期待的飲食，選擇相應情緒。', '對未來飲食的期待，能影響當下情緒狀態。透過味覺想像，可建立正向前瞻感，為日常行程帶來動力，並減輕疲倦與沉悶感。', 'Anticipation shapes present emotion and builds positivity.', '港鐵站(烏溪沙)、港鐵站(東涌)、港鐵站(筲箕灣)', 'MTR(Wu Kai Sha), MTR(Tung Chung), MTR(Shau Kei Wan)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"wks","name_zh":"港鐵站(烏溪沙)","name_en":"MTR(Wu Kai Sha)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.429139374489868,"lng":114.24384137143883,"x":70.63,"y":40.93},{"brand":"MTR","code":"tch","name_zh":"港鐵站(東涌)","name_en":"MTR(Tung Chung)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.28925399470771,"lng":113.94143667825882,"x":24.13,"y":59.41},{"brand":"MTR","code":"skw","name_zh":"港鐵站(筲箕灣)","name_en":"MTR(Shau Kei Wan)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.279242179506415,"lng":114.22888007055228,"x":71.12,"y":66.09}]', '{"message_zh":"您為未來保留了一點期待。\\n前面，仍然有值得等的事。\\n","message_en":"There are things to look forward to.","question_zh":"想到那份期待的味道時，您的心情是？","question_en":"How does thinking about that anticipated taste make you feel?","options":[{"label_zh":"愉快","label_en":"Happy","value":"a","message_zh":"您為未來保留了一點期待。\\n前面，仍然有值得等的事。\\n","message_en":"There are things to look forward to."},{"label_zh":"有點期待","label_en":"Reassured","value":"b","message_zh":"您為未來保留了一點期待。\\n前面，仍然有值得等的事。\\n","message_en":"There are things to look forward to."},{"label_zh":"平常","label_en":"Slightly excited","value":"c","message_zh":"您為未來保留了一點期待。\\n前面，仍然有值得等的事。\\n","message_en":"There are things to look forward to."}]}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(18, 'taste-imagination', 'painting', 'G4', 'Taste Imagination', '味覺想像', 'Imagine a taste that brings you comfort, and choose the feeling closest to it.', '想像一種令您安心的味道，選擇最貼近的感受。', '即使只是想像味道，也能引發身體與情緒反應。透過味覺想像，有助建立心理上的安全感，讓身心在繁忙之中獲得片刻放鬆。', 'Imagined taste can evoke comfort and relaxation.', '港鐵站(葵芳)、港鐵站(樂富)、港鐵站(兆康)、港鐵站(美孚-荃灣線)', 'MTR(Kwai Fong), MTR(Lok Fu), MTR(Siu Hong), MTR(Mei Foo-TWL)', '/assets/images/mission-cover/mtr.svg', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"kff","name_zh":"港鐵站(葵芳)","name_en":"MTR(Kwai Fong)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.356829101284756,"lng":114.12781358240389,"x":49.61,"y":49.4},{"brand":"MTR","code":"lfu","name_zh":"港鐵站(樂富)","name_en":"MTR(Lok Fu)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.338024821287,"lng":114.18702297593771,"x":61.62,"y":51.19},{"brand":"MTR","code":"shg","name_zh":"港鐵站(兆康)","name_en":"MTR(Siu Hong)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.411752477999226,"lng":113.97899651886509,"x":26.74,"y":40.15},{"brand":"MTR","code":"mfo","name_zh":"港鐵站(美孚-荃灣線)","name_en":"MTR(Mei Foo-TWL)","address_zh":"","address_en":"","max_distance":500.0,"lat":22.33757983812467,"lng":114.13798614736626,"x":52.42,"y":53.74}]', '{"message_zh":"您為自己創造了一個安心畫面。\\n想像，也是一種休息。\\n","message_en":"Imagination can be rest."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(19, 'walking-scenery', 'walking', 'T1', 'Walking Scenery', '行走的風景', 'Start the mission by tapping “Start Tracking.” Walk naturally around the mall and let the distance accumulate automatically. Once the required distance is reached, the system will display the completion screen. Tap “Complete Mission” to save your progress. There is no need to walk faster—simply focus on the act of walking itself.', '任務點開始，按下「開始追蹤」，於商場內自然步行即可累積距離。
完成指定距離後，系統會自動顯示任務完成畫面，點擊「完成任務」即可記錄成果。
無需加快步伐，專注行走本身。', '在日常移動之中，我們往往只顧目的地，而忽略了身體正在經歷的過程。這段短短的步行，並不是為了走得更快，而是讓您重新感受腳步與地面的接觸、呼吸的節奏，以及身體正在前行的感覺。停一停，行一步，其實已經是一種照顧自己的方式。', 'In daily movement, we often focus only on the destination and overlook what our body is experiencing along the way. This short walk is not about going faster, but about reconnecting with the contact between your feet and the ground, your breathing rhythm, and the sensation of your body moving forward. Pause for a moment—each step can be a way of caring for yourself.', 'PopCorn、青衣城、新屯門商場、圍方', 'PopCorn, Maritime Square, STM Shopping Center, The wai', '/assets/icons/mtr-mall.png', '2026-03-01 00:00:00', '2026-03-21 23:59:59', 'mtr', '[{"brand":"MTR","code":"tko","name_zh":"PopCorn","name_en":"PopCorn","address_zh":"將軍澳唐賢街9號","address_en":"9 Tong Yin Street, Tseung Kwan O","max_distance":500.0,"lat":22.308051696327745,"lng":114.25928132307621,"x":74.03,"y":57.29},{"brand":"MTR","code":"tyi","name_zh":"青衣城","name_en":"Maritime Square","address_zh":"青衣青敬路31-33號","address_en":"31-33 Tsing King Road, Tsing Yi","max_distance":500.0,"lat":22.358440896128123,"lng":114.10814654498527,"x":47.01,"y":52.19},{"brand":"MTR","code":"stm","name_zh":"新屯門商場","name_en":"STM Shopping Center","address_zh":"屯門龍門路55-65號","address_en":"55-65 Lung Mun Road, Tuen Mun","max_distance":500.0,"lat":22.381247838357908,"lng":113.96435525312341,"x":23.36,"y":47.35},{"brand":"MTR","code":"twa","name_zh":"圍方","name_en":"The wai","address_zh":"沙田大圍車公廟路18號","address_en":"18 Che Kung Miu Road, Tai Wai","max_distance":500.0,"lat":22.372556515867,"lng":114.17975349545246,"x":55.71,"y":43.16}]', '{"message_zh":"您已完成這段步行。\\n距離不長，但請記住身體前行的感覺。","message_en":"You have completed this walk. The distance was not long, but remember the feeling of your body moving forward.","required_distance":30}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(20, 'checkpoint-arrival', 'reflection', 'V1', 'Checkpoint Arrival', '到此一站', 'When you reach the designated checkpoint, the system will confirm your arrival via GPS. No check-in and no photos are required. Simply being present at this location is enough to complete the mission. Pause for a moment and notice yourself standing within the city.', '當您走到指定 Check Point，系統會透過 GPS 確認您已到達此地點。唔需要打卡、唔需要影相，只要您喺呢一刻，真正站喺呢個位置，就可以完成任務。請停一停，感受自己身處城市之中。', '生活每日都在催促我們趕路，我們卻很少問自己身在何處。當定位顯示已到達，並不只是座標被確認，而是您與這個空間短暫重疊。請留意腳下的觸感、周圍的聲音與空氣流動，讓身體知道：我在這裡。', 'Life constantly urges us to move faster, yet we rarely ask ourselves where we truly are. When your location is confirmed, it is not just a coordinate—it is a brief overlap between you and this space. Notice the texture beneath your feet, the surrounding sounds, and the movement of air, reminding yourself: I am here.', '牧羊少年 (九龍灣)、牧羊少年 (旺角)', 'Alchemist Cafe (Kowloon Bay), Alchemist Cafe (Mong Kok)', '/assets/images/mission-cover/thealchemistcafe.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'thealchemistcafe', '[{"brand":"牧羊少年","code":"klb","name_zh":"牧羊少年 (九龍灣)","name_en":"Alchemist Cafe (Kowloon Bay)","address_zh":"九龍灣偉業街33號德福廣場1期平台P26號舖","address_en":"Shop P26, Podium, Telford Plaza 1, 33 Wai Yip Street, Kowloon Bay","max_distance":100,"lat":22.322528731058334,"lng":114.21222197311029,"x":62.77,"y":54.12},{"brand":"牧羊少年","code":"mk","name_zh":"牧羊少年 (旺角)","name_en":"Alchemist Cafe (Mong Kok)","address_zh":"旺角彌敦道625 及639 雅蘭商場1樓103號舖","address_en":"Shop 103, 1/F, Grand Plaza, No. 625 & 639 Nathan Road, Mong Kok","max_distance":500.0,"lat":22.317963169201438,"lng":114.16943383420094,"x":59.55,"y":59.17}]', '{"message_zh":"恭喜您已到達目的地。\\n不是因為 GPS，而是因為您來過、站過、感受過。\\n繼續前行之前，記住這一刻的存在感。","message_en":"Congratulations on reaching this destination. Not because of GPS, but because you came, stood here, and truly felt this place."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(21, 'tabletop-scenery', 'photo', 'V1', 'Tabletop Scenery', '桌上的風景', 'Use the dayday filter to take a photo of your meal. There is no need to pose—simply capture this moment of sharing a meal with dayday. You may photograph the food, the table, or the scene of you dining together. Once the photo is taken, the mission is complete.', '使用 dayday 濾鏡拍下您正在吃的食物。
不用特別擺拍，
只要記錄這一餐與 dayday 一起的時刻。

您可以拍下食物、桌面，
或您與 dayday 同桌的畫面。
完成拍照，即完成任務。', '有人一起吃飯，
食物總是變得不一樣。

透過 dayday 的視角，
看看眼前這一餐的顏色、形狀與溫度。
不用急着吃，
先讓畫面停留一會。

這一刻，
有陪伴在桌上，
味道自然多了一點。', 'When we eat with someone, food often tastes different. Through dayday’s perspective, observe the colors, shapes, and warmth of this meal. There is no rush to eat—let the image linger for a moment. With companionship at the table, the flavor naturally deepens.', '牧羊少年 (銅鑼灣)、牧羊少年 (日出康城)、牧羊少年 (將軍澳香港單車館)', 'Alchemist Cafe (Causeway Bay), Alchemist Cafe (The LOHAS), Alchemist Cafe (Hong Kong Velodrome)', '/assets/images/mission-cover/thealchemistcafe.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'thealchemistcafe', '[{"brand":"牧羊少年","code":"cwb","name_zh":"牧羊少年 (銅鑼灣)","name_en":"Alchemist Cafe (Causeway Bay)","address_zh":"銅鑼灣記利佐治街 Fashion Walk G17號舖","address_en":"Shop G17, Fashion Walk, Great George Street, Causeway Bay","max_distance":100,"lat":22.28102697886984,"lng":114.18516255561313,"x":61.18,"y":63.94},{"brand":"牧羊少年","code":"lohas","name_zh":"牧羊少年 (日出康城)","name_en":"Alchemist Cafe (The LOHAS)","address_zh":"將軍澳康城路1號The LOHAS康城4樓417號舖","address_en":"Shop 417, Level 4, The Lohas, No. 1 Lohas Park Road, Tseung Kwan O, Sai Kung","max_distance":100,"lat":22.294284494694104,"lng":114.27064496496385,"x":74.53,"y":61.29},{"brand":"牧羊少年","code":"tko","name_zh":"牧羊少年 (將軍澳香港單車館)","name_en":"Alchemist Cafe (Hong Kong Velodrome)","address_zh":"將軍澳寶康路105-107號香港單車館地下G53號","address_en":"Shop G53, Hong Kong Velodrome, 105 Po Hong Road, Tseung Kwan O","max_distance":500.0,"lat":22.313289293819757,"lng":114.26219382585461,"x":73.38,"y":58.68}]', '{"message_zh":"這張照片，它記錄的不只是食物，\\n還有有dayday陪您吃飯的這一刻。\\n\\n原來一餐之所以好味，\\n有時，只是因為有人在旁。","message_en":"This photo records more than food—it captures the moment of sharing a meal with dayday. Sometimes, what makes a meal enjoyable is simply having company.","image_url":"/assets/images/frames/2.png"}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(22, 'letter-to-the-future', 'letter', 'V3', 'Letter to the Future', '給未來的信', 'In this mission, you will write a letter to yourself one year from now. You may type your thoughts, your current state, or moments you wish your future self to remember. You can also write about your goals, present feelings, or words you wish to say to your future self. Once completed, the letter will be saved and sent.', '在這個任務中，
您將寫一封信給一年後的自己。

您可以打字，記下此刻的您正在想的事，
正在經歷的狀態，或者您希望未來的自己
仍然記得的畫面與細節。

您也可以寫下：對未來的目標或方向
現在的感受與想法
想對未來的自己說的話
完成後，
這封信將被保存並寄出。
一年後，您會再次收到它。', '當您把感覺化成文字，
不只是記錄當下，
也是為未來留下線索。
此刻的畫面、聲音、氣味與觸感，
正悄悄標記您與世界的距離。
願一年後的您，
能從這些細節中，
再次遇見今天的自己。', 'When feelings are turned into words, you are not only recording the present, but also leaving clues for the future. Images, sounds, scents, and sensations quietly mark your distance from the world. May your future self rediscover today’s you through these details.', '牧羊少年與他的浮萍、牧羊少年 (尖沙咀)、牧羊少年 (葵芳)、牧羊少年 (大嶼山香港國際機場)', 'Lemna of the alchemist, Alchemist Cafe (Tsim Sha Tsui), Alchemist Cafe (Kwai Fong), Alchemist Cafe (Airport)', '/assets/images/mission-cover/thealchemistcafe.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'thealchemistcafe', '[{"brand":"牧羊少年","code":"tsw","name_zh":"牧羊少年與他的浮萍","name_en":"Lemna of the alchemist","address_zh":"尖沙咀梳士巴利道10號香港文化中心餐廳大樓地下","address_en":"G/F, Hong Kong Cultural Centre, 10 Salisbury Road, Tsim Sha Tsui","max_distance":500.0,"lat":22.293793438713017,"lng":114.1712649705524,"x":57.57,"y":60.78},{"brand":"牧羊少年","code":"tst","name_zh":"牧羊少年 (尖沙咀)","name_en":"Alchemist Cafe (Tsim Sha Tsui)","address_zh":"尖沙咀河內道18號K11購物藝術館B2樓27號舖(尖沙咀港鐵站D3出口)","address_en":"Shop 27, Basement 2, K11 Art Mall, 18 Hanoi Road, Tsim Sha Tsui","max_distance":500.0,"lat":22.297275825663487,"lng":114.17333638437323,"x":58.34,"y":61.31},{"brand":"牧羊少年","code":"kff","name_zh":"牧羊少年 (葵芳)","name_en":"Alchemist Cafe (Kwai Fong)","address_zh":"葵芳興寧路12號葵青劇院地下2號舖","address_en":"Shop 2, G/F, Kwai Tsing Theatre, 12 Hing Ning Road, Kwai Fong","max_distance":500.0,"lat":22.356380737441864,"lng":114.12621959021358,"x":49.7,"y":48.3},{"brand":"牧羊少年","code":"air","name_zh":"牧羊少年 (大嶼山香港國際機場)","name_en":"Alchemist Cafe (Airport)","address_zh":"大嶼山香港國際機場一號客運大樓第五層5T150號舖","address_en":"Unit No. 5T150, Level 5, Arrivals Meeters & Greeters Hall, Terminal 1, Hong Kong International Airport, Lantau Island, Hong Kong","max_distance":500.0,"lat":22.31608399290119,"lng":113.93576592922736,"x":17.48,"y":59.28}]', '{"message_zh":"這封信，\\n已為您寄出，\\n一年後，當文字再次出現，\\n它或許會提醒您，\\n曾經如何感受世界、\\n又如何在其中站立。\\n願這些留下的痕跡，\\n成為您再次遇見自己的入口。","message_en":"Your letter has been sent. When these words reappear one year later, they may remind you how you once felt the world and how you stood within it."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(23, 'sensory-matching-game', 'matching', 'V3', 'Sensory Matching Game', '五感對對碰', 'In this matching game, the images on the cards represent everyday sensory cues. Flipping, remembering, and matching the cards not only tests memory, but also invites you to slow down and notice how you observe and focus.', '在這個對對碰遊戲中，卡牌上的圖像代表不同的日常感官線索。翻牌、記住、配對的過程，不只考驗記憶力，也邀請您放慢節奏，留意自己如何用眼睛觀察、用身體感受節奏與專注。每一次成功配對，都是一次重新連結感覺的練習。', '我們每天接收大量感官刺激，卻很少真正停下來整理。當您專注翻開每一張卡牌，眼睛在找線索，身體在記住位置，大腦慢慢進入當下。這種專注的片刻，有助減少雜念，讓感覺重新變得清晰而穩定。', 'We receive countless sensory inputs every day, yet rarely pause to organize them. As you focus on each card, your eyes search for clues, your body remembers positions, and your mind gradually settles into the present moment.', '牧羊少年 (沙田)、牧羊少年 (深水埗)、牧羊少年 (屯門)', 'Alchemist Cafe (Sha Tin), Alchemist Cafe (Sham Shui Po), Alchemist Cafe (Tuen Mun)', '/assets/images/mission-cover/thealchemistcafe.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'thealchemistcafe', '[{"brand":"牧羊少年","code":"sti","name_zh":"牧羊少年 (沙田)","name_en":"Alchemist Cafe (Sha Tin)","address_zh":"沙田文林路1號香港文化博物館G6號","address_en":"Shop G6, Hong Kong Heritage Museum, 1 Man Lam Road, Sha Tin","max_distance":500.0,"lat":22.37687820754333,"lng":114.18537347888868,"x":58.56,"y":42.16},{"brand":"牧羊少年","code":"ssp","name_zh":"牧羊少年 (深水埗)","name_en":"Alchemist Cafe (Sham Shui Po)","address_zh":"深水埗白楊街27-29號嘉安大廈地下1號舖","address_en":"Shop 1, G/F, Ka On Building, 27-29 Poplar Street, Prince Edward, Kowloon","max_distance":500.0,"lat":22.327851533298297,"lng":114.16764113541325,"x":57.66,"y":55.51},{"brand":"牧羊少年","code":"tum","name_zh":"牧羊少年 (屯門)","name_en":"Alchemist Cafe (Tuen Mun)","address_zh":"屯門屯順街1號屯門市廣場1期2樓2151號舖","address_en":"Shop 2151, 2/F, Tuen Mun Town Plaza, 1 Tuen Shun Street, Tuen Mun","max_distance":500.0,"lat":22.39280784306846,"lng":113.97806042108506,"x":21.1,"y":43.71}]', '{"message_zh":"您已完成了一次小小的感官整理。\\n原來慢一點去看、去記、去感受，並不浪費時間。\\n這份專注，可以帶回您的日常之中。","message_en":"You have completed a small sensory reset. Slowing down to observe, remember, and feel is never a waste of time.","cards":[{"id":1,"image":"/assets/images/matching/330.svg"},{"id":2,"image":"/assets/images/matching/day1.svg"},{"id":3,"image":"/assets/images/matching/day2.svg"},{"id":4,"image":"/assets/images/matching/eslite.svg"},{"id":5,"image":"/assets/images/matching/day3.svg"},{"id":6,"image":"/assets/images/matching/day4.svg"},{"id":7,"image":"/assets/images/matching/day5.svg"},{"id":8,"image":"/assets/images/matching/thealchemistcafe.svg"}]}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(24, 'tabletop-scenery-cafe330', 'photo', 'V1', 'Tabletop Scenery', '桌上的風景', 'Use the dayday filter to take a photo of your meal. There is no need to pose—simply capture this moment of sharing a meal with dayday. You may photograph the food, the table, or the scene of you dining together. Once the photo is taken, the mission is complete.', '使用 dayday 濾鏡拍下您正在吃的食物。
不用特別擺拍，
只要記錄這一餐與 dayday 一起的時刻。

您可以拍下食物、桌面，
或您與 dayday 同桌的畫面。
完成拍照，即完成任務。', '有人一起吃飯，
食物總是變得不一樣。

透過 dayday 的視角，
看看眼前這一餐的顏色、形狀與溫度。
不用急着吃，
先讓畫面停留一會。

這一刻，
有陪伴在桌上，
味道自然多了一點。', 'When we eat with someone, food often tastes different. Through dayday’s perspective, observe the colors, shapes, and warmth of this meal. There is no rush to eat—let the image linger for a moment. With companionship at the table, the flavor naturally deepens.', 'cafe330 (香港大學)、cafe330 (廣華醫院)、cafe330 (明愛醫院)', '#N/A, cafe330 (Kwong Wah Hospital), cafe330 (Caritas Medical Centre)', '/assets/images/mission-cover/cafe330.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'cafe330', '[{"brand":"Cafe 330","code":"hku","name_zh":"cafe330 (香港大學)","name_en":"#N/A","address_zh":"薄扶林香港大學莊月明文娛中心2樓203室","address_en":"Room 203, 2/F., Chong Yuet Ming Amenities Centre, the University of Hong Kong, Pokfulam, HK","max_distance":500.0,"lat":22.282660021322638,"lng":114.13905024304881,"x":54.12,"y":63.95},{"brand":"Cafe 330","code":"mk","name_zh":"cafe330 (廣華醫院)","name_en":"cafe330 (Kwong Wah Hospital)","address_zh":"旺角窩打老道25號廣華醫院新大樓地下大堂中庭","address_en":"Portion of G/F, New Main Building, Kwong Wah Hospital, 25 Waterloo Road, Yau Ma Tei, Kowloon","max_distance":500.0,"lat":22.31450258234127,"lng":114.17193865214698,"x":58.07,"y":58.24},{"brand":"Cafe 330","code":"csw","name_zh":"cafe330 (明愛醫院)","name_en":"cafe330 (Caritas Medical Centre)","address_zh":"長沙灣永康街111號明愛醫院懷信樓4樓","address_en":"4/F Wai Shun Block, Caritas Medical Centre, 111 Wing Hong Street, Sham Shui Po, Kowloon","max_distance":500.0,"lat":22.34116525956304,"lng":114.15286844110452,"x":57.61,"y":51.47}]', '{"message_zh":"這張照片，它記錄的不只是食物，\\n還有有dayday陪您吃飯的這一刻。\\n\\n原來一餐之所以好味，\\n有時，只是因為有人在旁。","message_en":"This photo records more than food—it captures the moment of sharing a meal with dayday. Sometimes, what makes a meal enjoyable is simply having company.","image_url":"/assets/images/frames/1.png"}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(25, 'a-moment-with-day-day', 'ar', 'V3', 'A Moment with Day Day', '與 Day Day 相遇', 'Dayday is waiting for you at cafe330. Open AR and you will see dayday appear before you. Try moving around, crouching, stepping closer or further away, and capture this moment of meeting.', 'dayday 已經喺 cafe330 等待您。
打開 AR，佢就會出現喺您眼前——請試下移動一下位置、蹲低、拉遠、靠近，
讓dayday在現實中陪伴您，記得影低呢個相遇嘅瞬間啦。', '當虛擬影像與現實空間重疊，我們以為只是畫面改變，其實感受也在調整。當您移動視角、重新定位自己與世界的距離，身體與心會悄悄回應。這一刻，讓您看見的不只是世界，還有自己如何存在其中。', 'When virtual imagery overlaps with physical space, it may seem like only the visuals change—but feelings shift as well. As you adjust your perspective and distance, your body and mind quietly respond, revealing not only the world, but how you exist within it.', 'cafe330 (威爾斯親王醫院)、so330', 'cafe330 (Prince of Wales Hospital), so330', '/assets/images/mission-cover/so330.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'cafe330', '[{"brand":"Cafe 330","code":"sti","name_zh":"cafe330 (威爾斯親王醫院)","name_en":"cafe330 (Prince of Wales Hospital)","address_zh":"沙田銀城街30-32號威爾斯親王醫院住院主樓暨創傷中心1樓","address_en":"Level 1, Main Clinical Block & Trauma Centre, Prince of Wales Hospital, 30-32 Ngan Shing Street, Shatin","max_distance":500.0,"lat":22.380719639871778,"lng":114.20231743376604,"x":63.19,"y":45.0},{"brand":"so330","code":"wch","name_zh":"so330","name_en":"so330","address_zh":"灣仔太原街38號太源閣地下A-C舖","address_en":"Shop A-C, G/F, Tai Yuen Court, 38 Tai Yuen Street, Wan Chai, HK","max_distance":500.0,"lat":22.275201436968388,"lng":114.1733831091206,"x":59.74,"y":66.41}]', '{"message_zh":"您已完成「與 Day Day 相遇」。\\n請保存這張合照，\\n記住這次與 Day Day、\\n以及與當下相遇的瞬間。","message_en":"You have completed “A Moment with Day Day.” Please save this photo and remember this moment of meeting dayday—and the present moment itself."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(26, 'checkpoint-arrival-eslite', 'reflection', 'V3', 'Checkpoint Arrival', '到此一站', 'When you reach the designated checkpoint, the system will confirm your arrival via GPS. No check-in and no photos are required. Simply being present at this location is enough to complete the mission. Pause for a moment and notice yourself standing within the city.', '當您走到指定 Check Point，系統會透過 GPS 確認您已到達此地點。唔需要打卡、唔需要影相，只要您喺呢一刻，真正站喺呢個位置，就可以完成任務。請停一停，感受自己身處城市之中。', '生活每日都在催促我們趕路，我們卻很少問自己身在何處。當定位顯示已到達，並不只是座標被確認，而是您與這個空間短暫重疊。請留意腳下的觸感、周圍的聲音與空氣流動，讓身體知道：我在這裡。', 'Life constantly urges us to move faster, yet we rarely ask ourselves where we truly are. When your location is confirmed, it is not just a coordinate—it is a brief overlap between you and this space. Notice the texture beneath your feet, the surrounding sounds, and the movement of air, reminding yourself: I am here.', '誠品(荃灣)、誠品(奧運)、誠品(屯門)', 'Eslite (Tsuen Wan), Eslite (Olympic), Eslite (Tuen Mun)', '/assets/images/mission-cover/eslite.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'eslite', '[{"brand":"Eslite","code":"tww","name_zh":"誠品(荃灣)","name_en":"Eslite (Tsuen Wan)","address_zh":"香港荃灣青山公路荃灣段398號D•PARK愉景新城第一層1010-1013舖","address_en":"Shop 1010-1013, Level 1, D·PARK, 398 Castle Peak Road, Tsuen Wan, Hong Kong","max_distance":500.0,"lat":22.376338108660207,"lng":114.11209966474236,"x":48.05,"y":47.49},{"brand":"Eslite","code":"oly","name_zh":"誠品(奧運)","name_en":"Eslite (Olympic)","address_zh":"香港九龍大角咀海泓道1號奧海城三期地下高層UG55-58, 80-88號舖","address_en":"UG55-58, 80-88, UG/F, Olympian City 3, 1 Hoi Wang Road, Kowloon, Hong Kong","max_distance":500.0,"lat":22.31748113740108,"lng":114.16480748532314,"x":57.16,"y":57.91},{"brand":"Eslite","code":"tum","name_zh":"誠品(屯門)","name_en":"Eslite (Tuen Mun)","address_zh":"香港屯門新墟屯門鄉事會路83號 V city MTR層M18號舖","address_en":"Shop M18, MTR Level, V city, 83 Tuen Mun Heung Sze Wui Road, Tuen Mun, Hong Kong","max_distance":500.0,"lat":22.39539289844076,"lng":113.97390719548207,"x":20.2,"y":43.72}]', '{"message_zh":"恭喜您已到達目的地。\\n不是因為 GPS，而是因為您來過、站過、感受過。\\n繼續前行之前，記住這一刻的存在感。","message_en":"Congratulations on reaching this destination. Not because of GPS, but because you came, stood here, and truly felt this place."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(27, 'a-moment-with-day-day-eslite', 'ar', 'V3', 'A Moment with Day Day', '與 Day Day 相遇', 'Open AR and allow the virtual image to overlap with the real world.
Move your position, step closer or further away, and adjust your view to notice the moment when the world begins to feel different.
When you are ready, take a photo with Day Day and capture this moment —
a small record of your encounter.', '挑戰指令
開啟 AR，讓虛擬畫面與現實重疊。
請移動位置、拉近或拉遠視角，
找出世界出現變化的一刻。
當您準備好，
與 Day Day 一起影下這個瞬間，
將這次相遇留作紀念。', '當虛擬影像與現實空間重疊，我們以為只是畫面改變，其實感受也在調整。當您移動視角、重新定位自己與世界的距離，身體與心會悄悄回應。這一刻，讓您看見的不只是世界，還有自己如何存在其中。', 'When virtual imagery overlaps with physical space, it may seem like only the visuals change—but feelings shift as well. As you adjust your perspective and distance, your body and mind quietly respond, revealing not only the world, but how you exist within it.', '誠品(銅鑼灣)、誠品(尖沙咀)、誠品(太古)', 'Eslite (Causeway Bay), Eslite (Tsim Sha Tsui), Eslite (Tai Koo)', '/assets/images/mission-cover/eslite.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'eslite', '[{"brand":"Eslite","code":"cwb","name_zh":"誠品(銅鑼灣)","name_en":"Eslite (Causeway Bay)","address_zh":"香港銅鑼灣軒尼詩道500號希慎廣場8/F-10/F","address_en":" \\n8/F-10/F Hysan Place, 500 Hennessy Road, Causeway Bay, Hong Kong","max_distance":500.0,"lat":22.27970223724613,"lng":114.18384567001003,"x":61.92,"y":65.5},{"brand":"Eslite","code":"tsw","name_zh":"誠品(尖沙咀)","name_en":"Eslite (Tsim Sha Tsui)","address_zh":"香港尖沙咀梳士巴利道3號星光行2/F-3/F","address_en":"2/F-3/F Star House, 3 Salisbury Road, Tsim Sha Tsui, Hong Kong","max_distance":500.0,"lat":22.29451250649383,"lng":114.16882313698387,"x":57.2,"y":60.46},{"brand":"Eslite","code":"tko","name_zh":"誠品(太古)","name_en":"Eslite (Tai Koo)","address_zh":"香港太古城道18號太古城中心G/F 74鋪及1/F 144鋪","address_en":"Shop 074,G/F & Shop 144, 1/F Cityplaza, 18 Tai Koo Shing Road, Hong Kong","max_distance":500.0,"lat":22.28562360835834,"lng":114.21799285775647,"x":67.56,"y":64.85}]', '{"message_zh":"您已完成「與 Day Day 相遇」。\\n請保存這張合照，\\n記住這次與 Day Day、\\n以及與當下相遇的瞬間。","message_en":"You have completed “A Moment with Day Day.” Please save this photo and remember this moment of meeting dayday—and the present moment itself."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(28, 'sensory-matching-game-eslite', 'matching', 'V3', 'Sensory Matching Game', '五感對對碰', 'In this matching game, the images on the cards represent everyday sensory cues. Flipping, remembering, and matching the cards not only tests memory, but also invites you to slow down and notice how you observe and focus.', '在這個對對碰遊戲中，卡牌上的圖像代表不同的日常感官線索。翻牌、記住、配對的過程，不只考驗記憶力，也邀請您放慢節奏，留意自己如何用眼睛觀察、用身體感受節奏與專注。每一次成功配對，都是一次重新連結感覺的練習。', '我們每天接收大量感官刺激，卻很少真正停下來整理。當您專注翻開每一張卡牌，眼睛在找線索，身體在記住位置，大腦慢慢進入當下。這種專注的片刻，有助減少雜念，讓感覺重新變得清晰而穩定。', 'We receive countless sensory inputs every day, yet rarely pause to organize them. As you focus on each card, your eyes search for clues, your body remembers positions, and your mind gradually settles into the present moment.', '誠品(九龍塘)、誠品(啟德)、誠品(大圍)', 'Eslite (Kowloon Tong), Eslite (Kai Tak), Eslite (Tai Wai)', '/assets/images/mission-cover/eslite.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'eslite', '[{"brand":"Eslite","code":"ktt","name_zh":"誠品(九龍塘)","name_en":"Eslite (Kowloon Tong)","address_zh":"香港九龍塘達之路80號又一城LG2-02B號鋪","address_en":"Shop No. LG2-02B, Festival Walk, 80 Tat Chee Avenue, Kowloon Tong, Hong Kong","max_distance":500.0,"lat":22.3367643332952,"lng":114.17519760231535,"x":59.92,"y":53.07},{"brand":"Eslite","code":"kit","name_zh":"誠品(啟德)","name_en":"Eslite (Kai Tak)","address_zh":"香港九龍新蒲崗太子道東638號 Mikiki 115-115A 號舖","address_en":"638 Prince Edward Road East, San Po Kong, Kowloon, Hong Kong (Mikiki Shop No. 115-115A)","max_distance":500.0,"lat":22.333268090294567,"lng":114.19681313371507,"x":62.76,"y":54.12},{"brand":"Eslite","code":"twa","name_zh":"誠品(大圍)","name_en":"Eslite (Tai Wai)","address_zh":"香港沙田大圍車公廟路18號THE WAI 5樓508-509號舖","address_en":"Shop No. 508-509, 5/F, THE WAI, 18 Che Kung Temple Road, Tai Wai, Hong Kong","max_distance":500.0,"lat":22.372491588715633,"lng":114.1789008702305,"x":55.73,"y":43.16}]', '{"message_zh":"您已完成了一次小小的感官整理。\\n原來慢一點去看、去記、去感受，並不浪費時間。\\n這份專注，可以帶回您的日常之中。","message_en":"You have completed a small sensory reset. Slowing down to observe, remember, and feel is never a waste of time.","cards":[{"id":1,"image":"/assets/images/matching/330.svg"},{"id":2,"image":"/assets/images/matching/day1.svg"},{"id":3,"image":"/assets/images/matching/day2.svg"},{"id":4,"image":"/assets/images/matching/eslite.svg"},{"id":5,"image":"/assets/images/matching/day3.svg"},{"id":6,"image":"/assets/images/matching/day4.svg"},{"id":7,"image":"/assets/images/matching/day5.svg"},{"id":8,"image":"/assets/images/matching/thealchemistcafe.svg"}]}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(29, 'tamjai', 'tamjai', 'G4', 'Rice Noodle Moment', '一碗米線的時間', 'In the fast pace of city life, eating often becomes just another task to finish quickly.330day invites you to pause, even in a familiar dining setting.
Through sight, smell, sound, taste, and touch, rediscover the moment of focus a bowl of Mixian can bring.This experience has no time limit and requires no change in choice—simply move through each step at your own pace.
Let one meal become a small pause, and a moment of reconnection with yourself.
', '在城市的日常節奏中，飲食往往只是其中一個被快速完成的環節。330day 邀請您，在熟悉的用餐場景中，暫停一下腳步。透過視覺、嗅覺、聽覺、味覺與觸覺，重新感受一碗米線帶來的專注片刻。這次體驗不設時間限制，也無需改變選擇，只需按自己的節奏完成每一個步驟。讓一餐，成為與自己連結的微小休息。
', '/', '/', '所有譚仔分店', 'All TamJai Shop', '/assets/images/mission-cover/tamjai.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'tamjai', '[{"brand":"譚仔","code":"all","name_zh":"所有譚仔分店","name_en":"All TamJai Shop","address_zh":"","address_en":"","max_distance":100,"lat":0,"lng":0,"x":0,"y":0}]', '{"message_zh":"您已完成五感慢食之旅\\n飲食內容沒有改變，\\u000b改變的是進食時的專注程度。\\n","message_en":"You Have Completed the Five-Senses Dining Journey \\nThe food itself hasn’t changed.\\u000bWhat changed is the level of attention while eating."}');

INSERT INTO tbl_mission (id, slug, type, code, name_en, name_zh, description_en, description_zh, wellness_message_zh, wellness_message_en, address_zh, address_en, cover_image, start_time, end_time, category, location, parameter) VALUES
(30, 'samgor', 'samgor', 'G4', 'Rice Noodle Moment', '一碗米線的時間', 'In the fast pace of city life, eating often becomes just another task to finish quickly.330day invites you to pause, even in a familiar dining setting.
Through sight, smell, sound, taste, and touch, rediscover the moment of focus a bowl of Mixian can bring.This experience has no time limit and requires no change in choice—simply move through each step at your own pace.
Let one meal become a small pause, and a moment of reconnection with yourself.
', '在城市的日常節奏中，飲食往往只是其中一個被快速完成的環節。330day 邀請您，在熟悉的用餐場景中，暫停一下腳步。透過視覺、嗅覺、聽覺、味覺與觸覺，重新感受一碗米線帶來的專注片刻。這次體驗不設時間限制，也無需改變選擇，只需按自己的節奏完成每一個步驟。讓一餐，成為與自己連結的微小休息。
', '/', '/', '所有三哥分店', 'All Samgor Shop', '/assets/images/mission-cover/samgor.svg', '2026-03-01 00:00:00', '2026-03-31 23:59:59', 'samgor', '[{"brand":"三哥","code":"all","name_zh":"所有三哥分店","name_en":"All Samgor Shop","address_zh":"","address_en":"","max_distance":100,"lat":0,"lng":0,"x":0,"y":0}]', '{"message_zh":"您已完成五感慢食之旅\\n飲食內容沒有改變，\\u000b改變的是進食時的專注程度。\\n","message_en":"You Have Completed the Five-Senses Dining Journey \\nThe food itself hasn’t changed.\\u000bWhat changed is the level of attention while eating."}');

